--
-- Name: gerar_hash_upload(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gerar_hash_upload() RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
    novo_hash VARCHAR(64);
    existe BOOLEAN;
BEGIN
    LOOP
        -- Gera hash com timestamp + random
        novo_hash := encode(
            sha256(
                (extract(epoch from now())::text || random()::text || random()::text)::bytea
            ),
            'hex'
        );
        -- Pega apenas 32 caracteres
        novo_hash := substring(novo_hash from 1 for 32);
        
        -- Verifica se já existe
        SELECT EXISTS(SELECT 1 FROM uploads_nf WHERE hash = novo_hash) INTO existe;
        
        IF NOT existe THEN
            RETURN novo_hash;
        END IF;
    END LOOP;
END;
$$;


--
-- Name: notificar_whatsapp_nf_recebida(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notificar_whatsapp_nf_recebida() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Verificar se o status mudou para N.F. RECEBIDA
    IF NEW.status = 'N.F. RECEBIDA' AND (OLD.status IS NULL OR OLD.status != 'N.F. RECEBIDA') THEN
        -- Inserir job na fila para processar
        VALUES (NEW.id, 'nf_recebida_prestador', NOW());
    END IF;
    
    RETURN NEW;
END;
$$;


