ALTER SEQUENCE public.uploads_nf_id_seq OWNED BY public.uploads_nf.id;


--
-- Name: v_uploads_pendentes; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_uploads_pendentes AS
 SELECT u.id,
    u.hash,
    u.tipo,
    u.lote_id,
    u.envio_montagem_id,
    u.status,
    u.data_criacao,
    u.data_expiracao,
    u.data_upload,
    u.sistema,
        CASE
            WHEN ((u.tipo)::text = 'prestador'::text) THEN l.prestador_nome
            WHEN ((u.tipo)::text = 'montador'::text) THEN e.montador_nome
            ELSE NULL::text
        END AS nome_entidade,
        CASE
            WHEN ((u.tipo)::text = 'prestador'::text) THEN l.periodo
            WHEN ((u.tipo)::text = 'montador'::text) THEN e.periodo
            ELSE NULL::text
        END AS periodo,
        CASE
            WHEN ((u.tipo)::text = 'prestador'::text) THEN l.valor_total
            WHEN ((u.tipo)::text = 'montador'::text) THEN (e.valor_total)::real
            ELSE NULL::real
        END AS valor_total,
    COALESCE(( SELECT count(*) AS count
           FROM public.uploads_nf_arquivos
          WHERE (uploads_nf_arquivos.upload_id = u.id)), (0)::bigint) AS total_arquivos
   FROM ((public.uploads_nf u
     LEFT JOIN public.lotes_servico l ON ((u.lote_id = l.id)))
     LEFT JOIN public.envios_montagem e ON ((u.envio_montagem_id = e.id)))
  WHERE ((u.status = 0) AND (u.data_expiracao > now()) AND ((u.sistema)::text = 'interno'::text));


